/**
 * @param {string} word1
 * @param {string} word2
 * @return {number[]}
 */
var validSequence = function (word1, word2) {
    const n = word1.length;
    const m = word2.length;
    const last = new Array(m).fill(-1);
    let j = m - 1;

    for (let i = n - 1; i >= 0; i--) {
        if (j >= 0 && word1[i] === word2[j]) {
            last[j] = i;
            j--;
        }
    }

    const res = [];
    let skipped = false;
    j = 0;

    for (let i = 0; i < n; i++) {
        if (j === m) {
            break;
        }

        const sameChar = word1[i] === word2[j];

        if (!sameChar && (skipped || (j !== m - 1 && i >= last[j + 1]))) {
            continue;
        }

        if (!sameChar) {
            skipped = true;
        }

        res.push(i);
        j++;
    }

    return j === m ? res : [];
};
